/**
 * Worker-trusted marker injected by Figma's sites-worker after it validates the
 * X-Figma-Job-Queues-Auth-Bypass secret on a Payload jobs endpoint. The default
 * `jobs.access.run` below honors this marker so Sinatra (async-job-workflow)
 * can drive job runs without the bypass secret ever reaching tenant code.
 *
 * KEEP_IN_SYNC(cloudflare/wrangler/sites-worker/src/auth.ts): FIGMA_INTERNAL_FORWARDED_HAS_AUTH_BYPASS_HEADER
 */ export const FIGMA_INTERNAL_FORWARDED_HAS_AUTH_BYPASS_HEADER = 'figma-internal-forwarded-has-auth-bypass';
/**
 * Fields added to the configured Payload Admin collection for Figma profile info
 */ const figmaUserFields = [
    {
        name: 'figmaHandle',
        type: 'text',
        admin: {
            readOnly: true
        },
        label: ({ t })=>t('general:name')
    },
    {
        name: 'figmaImageUrl',
        type: 'text',
        admin: {
            components: {
                Cell: '@payloadcms/figma/client#FigmaAvatarCell'
            },
            disabled: {
                bulkEdit: true
            },
            hidden: true,
            readOnly: true
        },
        label: ({ t })=>t('figma:profilePicture')
    },
    // Virtual (never persisted): populated per-request from the session JWT. The
    // afterRead hook surfaces the claim on the requester's OWN user record only —
    // a JWT describes its bearer, so these are meaningful for req.user, not for
    // reads of other users. See defaults.ts (defaultVerify) which attaches the
    // live claim to req.user.
    {
        name: 'userGroups',
        type: 'text',
        access: {
            read: ({ id, req })=>req.user?.id === id
        },
        admin: {
            readOnly: true
        },
        hasMany: true,
        hooks: {
            afterRead: [
                ({ data, req })=>data?.id !== undefined && req.user?.id === data.id ? req.user.userGroups : undefined
            ]
        },
        label: ({ t })=>t('figma:userGroups'),
        virtual: true
    },
    // KEEP_IN_SYNC(sinatra/controllers/api/api_payload_control_plane.rb) — resolve_make_permission
    {
        name: 'makePermission',
        type: 'select',
        access: {
            read: ({ id, req })=>req.user?.id === id
        },
        admin: {
            readOnly: true
        },
        hooks: {
            afterRead: [
                ({ data, req })=>data?.id !== undefined && req.user?.id === data.id ? req.user.makePermission : undefined
            ]
        },
        label: ({ t })=>t('figma:makePermission'),
        options: [
            {
                label: ({ t })=>t('figma:view'),
                value: 'view'
            },
            {
                label: ({ t })=>t('general:edit'),
                value: 'edit'
            }
        ],
        virtual: true
    }
];
function missingOAuthCredential(name) {
    log.warning(`${name} could not be resolved. OAuth login will not work until this is configured. ` + 'Run `npx @payloadcms/figma init` to set up your project.');
    return '';
}
/**
 * Fetch bootstrap data from the API and cache all environments locally.
 * Returns the requested environment's data, or a typed failure reason.
 */ async function resolveAndCacheBootstrap(store, projectId, environmentName) {
    let credential;
    try {
        credential = await getValidCredential(store);
    } catch (error) {
        return {
            ok: false,
            reason: {
                kind: 'network',
                message: messageOf(error)
            }
        };
    }
    if (!credential) {
        return {
            ok: false,
            reason: {
                kind: 'unauthenticated'
            }
        };
    }
    try {
        const bootstrapInfo = await getBootstrapInfo(credential, projectId);
        cacheAllEnvironments(store, projectId, bootstrapInfo);
    } catch (error) {
        return {
            ok: false,
            reason: {
                kind: 'network',
                message: messageOf(error)
            }
        };
    }
    const data = store.getBootstrapData(projectId, environmentName);
    if (!data) {
        return {
            ok: false,
            reason: {
                environmentName,
                kind: 'environment-not-found',
                projectId
            }
        };
    }
    return {
        data,
        ok: true
    };
}
/**
 * Project + environment named in process.env or .env. Uses getEnvVarSync because Next.js
 * evaluates config before dotenv populates process.env.
 */ function readProjectScope() {
    const projectId = process.env.FIGMA_PROJECT_ID ?? getEnvVarSync(process.cwd(), 'FIGMA_PROJECT_ID');
    const environmentName = process.env.FIGMA_ENVIRONMENT_NAME ?? getEnvVarSync(process.cwd(), 'FIGMA_ENVIRONMENT_NAME');
    if (!projectId || !environmentName) {
        return null;
    }
    return {
        environmentName,
        projectId
    };
}
function readCachedBootstrapData() {
    const scope = readProjectScope();
    return scope ? getTokenStore().getBootstrapData(scope.projectId, scope.environmentName) : null;
}
/**
 * Resolve the Content API base URL: FIGMA_CONTENT_API_URL (injected in deployed environments),
 * then the environment's regional URL from the bootstrap cache. A cached entry without a URL
 * (written before bootstrap returned one) is refreshed from the API, unless this build already
 * fetched bootstrap. Throws when no URL can be resolved.
 */ async function requireContentApiUrl(args) {
    if (process.env.FIGMA_CONTENT_API_URL) {
        return process.env.FIGMA_CONTENT_API_URL;
    }
    const cached = args.bootstrapData ?? readCachedBootstrapData();
    if (cached?.contentApiUrl) {
        return cached.contentApiUrl;
    }
    const scope = readProjectScope();
    if (!scope) {
        throw new Error('Could not resolve the Content API URL.');
    }
    const message = `Could not resolve the Content API URL for environment "${scope.environmentName}" of project ${scope.projectId}.`;
    if (args.bootstrapFetched) {
        throw new Error(message);
    }
    const resolution = await resolveAndCacheBootstrap(getTokenStore(), scope.projectId, scope.environmentName);
    if (!resolution.ok) {
        throw new Error(`${message} ${describeBootstrapFailure(resolution.reason)}`);
    }
    if (!resolution.data.contentApiUrl) {
        throw new Error(message);
    }
    return resolution.data.contentApiUrl;
}
function describeBootstrapFailure(reason) {
    switch(reason.kind){
        case 'environment-not-found':
            return 'Fetching bootstrap data failed: environment not found.';
        case 'network':
            return `Fetching bootstrap data failed: ${reason.message}`;
        case 'unauthenticated':
            return 'Fetching bootstrap data failed: not logged in.';
    }
}
function messageOf(error) {
    return error instanceof Error ? error.message : 'Unknown error';
}
/**
 * Local-dev fallback: if the tenant config didn't supply a secret (usually
 * because process.env.PAYLOAD_SECRET is unset), try the TokenStore cache,
 * then fetch from the Control Plane. Skipped in Lambda — the platform
 * injects PAYLOAD_SECRET as an env var there, and TokenStore throws in AWS.
 * Returns undefined if we can't resolve one; the caller lets payload.init()
 * throw its own error.
 */ async function resolvePayloadSecretForRuntime(store, projectId, environmentName, tenantInstanceId) {
    const cached = store.getPayloadSecret({
        projectInfo: {
            environmentName,
            projectId
        }
    });
    if (cached) {
        return cached;
    }
    let credential;
    try {
        credential = await getValidCredential(store);
    } catch (error) {
        log.debug(`PAYLOAD_SECRET fetch skipped: ${messageOf(error)}`);
        return undefined;
    }
    if (!credential) {
        log.debug('PAYLOAD_SECRET fetch skipped: no cached CLI credential');
        return undefined;
    }
    try {
        const secret = await getEnvironmentVariableByName(credential, tenantInstanceId, 'PAYLOAD_SECRET');
        store.setPayloadSecret({
            projectInfo: {
                environmentName,
                projectId
            },
            secret
        });
        return secret;
    } catch (error) {
        log.debug(`PAYLOAD_SECRET fetch failed: ${messageOf(error)}`);
        return undefined;
    }
}
/**
 * Creates storage configuration for upload collections
 */ function createStorageConfig(url, contentSystemId, uploadInstructionsAccess) {
    const storageConfig = {
        ...process.env.FIGMA_CONTENT_API_ACCESS_KEY ? {
            baseUrl: url,
            contentApiKey: process.env.FIGMA_CONTENT_API_ACCESS_KEY
        } : process.env.FIGMA_DEV_JWT === 'true' ? {
            auth: {
                mode: 'devJwt'
            },
            baseUrl: url,
            contentSystemId
        } : {
            auth: {
                mode: 'tokenStore',
                tokenStore: getTokenStore()
            },
            baseUrl: url,
            contentSystemId
        },
        uploadInstructionsAccess
    };
    const adapter = contentApiStorageAdapter(storageConfig);
    const storageClient = createStorageClient(storageConfig);
    return {
        adapter,
        storageClient
    };
}
/**
 * Plugin that applies cloud storage configuration to all upload-enabled collections.
 * Runs at the end of the plugin chain so it sees collections added by user plugins too.
 */ function createStoragePlugin(url, contentSystemId, uploadInstructionsAccess) {
    return (incomingConfig)=>{
        const uploadCollections = (incomingConfig.collections || []).filter((c)=>c.upload);
        if (uploadCollections.length === 0) {
            return incomingConfig;
        }
        const { adapter } = createStorageConfig(url, contentSystemId, uploadInstructionsAccess);
        const collectionsMap = uploadCollections.reduce((acc, c)=>{
            acc[c.slug] = {
                adapter,
                disableLocalStorage: true
            };
            return acc;
        }, {});
        const storagePlugin = cloudStoragePlugin({
            collections: collectionsMap
        });
        return storagePlugin(incomingConfig);
    };
}
export async function buildFigmaConfig(config) {
    const envConfig = getEnvConfig();
    // Resolve contentSystemId: config first, env var, then local store fallback (dev)
    let { contentSystemId } = config.figma;
    let environmentId = config.figma.environmentId ?? process.env.FIGMA_EID;
    contentSystemId ??= process.env.FIGMA_CONTENT_API_CONTENT_SYSTEM_ID;
    let bootstrapData = null;
    let bootstrapFetched = false;
    let bootstrapReason = null;
    // Local dev: resolve from project ID + bootstrap cache
    if (!contentSystemId) {
        const scope = readProjectScope();
        if (!scope) {
            bootstrapReason = {
                kind: 'no-config'
            };
        } else {
            const { environmentName, projectId } = scope;
            const store = getTokenStore();
            bootstrapData = store.getBootstrapData(projectId, environmentName);
            // Runtime fallback: fetch from API if not cached (e.g. environment switch without re-init)
            if (!bootstrapData) {
                bootstrapFetched = true;
                const resolution = await resolveAndCacheBootstrap(store, projectId, environmentName);
                if (resolution.ok) {
                    bootstrapData = resolution.data;
                } else {
                    bootstrapReason = resolution.reason;
                }
            }
            if (bootstrapData) {
                contentSystemId = bootstrapData.contentSystemId;
                environmentId ??= bootstrapData.tenantInstanceId;
            }
        }
    }
    if (!environmentId) {
        bootstrapData ??= readCachedBootstrapData();
        environmentId = bootstrapData?.tenantInstanceId;
    }
    if (!environmentId) {
        throw new Error('Environment ID could not be resolved. Set FIGMA_EID or initialize the project.');
    }
    if (!contentSystemId) {
        logMissingContentSystemId(bootstrapReason ?? {
            kind: 'no-config'
        });
        throw new Error('Content System ID could not be resolved. ' + 'Run `npx @payloadcms/figma init` to set up your project.');
    }
    // Only the content-system db adapter and cloud storage call the Content API, so a project on a
    // custom db with storage disabled needs no URL; `url` stays '' and is unused in that case.
    const usesContentSystem = config.figma.useContentSystem !== false;
    const url = usesContentSystem || config.figma.storage !== false ? await requireContentApiUrl({
        bootstrapData,
        bootstrapFetched
    }) : '';
    const isProduction = process.env.NODE_ENV === 'production';
    // The deployed Lambda runs all queued jobs; locally there is no runner, so the db adapter logs
    // a heads-up whenever a job is queued. Deployed environments set DISABLE_LOCAL_JOB_QUEUE_NOTIFICATIONS=true
    // (injected by the control plane); end-users can also set it locally to silence the notice.
    const notifyLocalJobQueue = process.env.DISABLE_LOCAL_JOB_QUEUE_NOTIFICATIONS !== 'true';
    const usesTokenStoreAuth = !process.env.FIGMA_CONTENT_API_ACCESS_KEY && process.env.FIGMA_DEV_JWT !== 'true';
    if (usesTokenStoreAuth) {
        logMissingCliAuth(getTokenStore());
    }
    // Determine database adapter based on environment
    let db;
    if (!usesContentSystem) {
        db = config.db;
    } else if (process.env.FIGMA_CONTENT_API_ACCESS_KEY) {
        db = contentAPIAdapter({
            auth: {
                apiKey: process.env.FIGMA_CONTENT_API_ACCESS_KEY,
                mode: 'apiKey'
            },
            contentSystemId,
            environmentName: process.env.FIGMA_ENVIRONMENT_NAME,
            notifyLocalJobQueue,
            url
        });
    } else if (process.env.FIGMA_DEV_JWT === 'true') {
        db = contentAPIAdapter({
            auth: {
                mode: 'devJwt'
            },
            contentSystemId,
            environmentName: process.env.FIGMA_ENVIRONMENT_NAME,
            notifyLocalJobQueue,
            url
        });
    } else {
        db = contentAPIAdapter({
            auth: {
                mode: 'tokenStore',
                tokenStore: getTokenStore()
            },
            contentSystemId,
            environmentName: process.env.FIGMA_ENVIRONMENT_NAME,
            notifyLocalJobQueue,
            url
        });
    }
    const userJobsAccessRun = config.jobs?.access?.run;
    const adminCollectionSlug = getAdminCollectionSlug(config);
    // Hosted runtimes inject the Content API key and PAYLOAD_SECRET together, so
    // the process env is authoritative. Ordinary local dev still checks the
    // TokenStore first so a leftover .env value cannot shadow the platform secret.
    let resolvedSecret;
    if (process.env.AWS_EXECUTION_ENV || process.env.FIGMA_CONTENT_API_ACCESS_KEY) {
        resolvedSecret = process.env.PAYLOAD_SECRET;
    } else {
        const projectId = process.env.FIGMA_PROJECT_ID ?? getEnvVarSync(process.cwd(), 'FIGMA_PROJECT_ID');
        const environmentName = process.env.FIGMA_ENVIRONMENT_NAME ?? getEnvVarSync(process.cwd(), 'FIGMA_ENVIRONMENT_NAME');
        if (projectId && environmentName && environmentId) {
            resolvedSecret = await resolvePayloadSecretForRuntime(getTokenStore(), projectId, environmentName, environmentId);
        }
        if (!resolvedSecret) {
            // Config may be evaluated before the framework loads dotenv. Parse the
            // file without mutating process.env, preserving quotes/comments correctly.
            resolvedSecret = process.env.PAYLOAD_SECRET || getParsedEnvVarSync(process.cwd(), 'PAYLOAD_SECRET') || undefined;
            if (resolvedSecret) {
                log.warning('Using a local PAYLOAD_SECRET fallback because the platform secret could not be resolved. ' + 'It may differ from the deployed secret. Run `npx @payloadcms/figma init --id <project-id> --force` to refresh it.');
            }
        }
    }
    // Build complete config with Figma platform defaults.
    // `secret` may be undefined here; payload.init() enforces its presence at
    // runtime, so we relax the intermediate type instead of forging a default.
    const configWithFigmaDefaults = {
        ...config,
        admin: {
            // Auto-refresh tokens before expiry to prevent unexpected logouts.
            autoRefresh: true,
            avatar: {
                Component: '@payloadcms/figma/client#FigmaAvatar'
            },
            ...config.admin,
            components: {
                ...config.admin?.components,
                providers: [
                    ...config.admin?.components?.providers ?? [],
                    '@payloadcms/figma/client#FigmaCloudLimitProvider'
                ]
            }
        },
        // Payload applies this policy during sanitization, after user plugins and
        // generated resources have registered their collections and globals.
        baseAccess: withMakeViewerWriteBaseAccessDefaults(config.baseAccess),
        custom: {
            figma: {
                ...config.figma,
                ...typeof config.figma.storage === 'object' ? {
                    storage: true
                } : {},
                contentSystemId,
                environmentId
            }
        },
        db,
        editor: config.editor ?? lexicalEditor(),
        endpoints: [
            ...config.endpoints ?? [],
            health,
            schema
        ],
        i18n: {
            ...config.i18n,
            translations: deepMergeSimple(figmaTranslations, config.i18n?.translations ?? {})
        },
        secret: resolvedSecret,
        // Gate /api/payload-jobs/run and /api/payload-jobs/handle-schedules. Honor the
        // sites-worker trust marker so Figma infra job runs never break, defer to the
        // tenant's jobs.access.run if they set one, otherwise require an authenticated
        // user who is not a known Make viewer.
        jobs: {
            ...config.jobs ?? {},
            access: {
                ...config.jobs?.access ?? {},
                run: (args)=>{
                    if (args.req.headers.get(FIGMA_INTERNAL_FORWARDED_HAS_AUTH_BYPASS_HEADER) === '1') {
                        return true;
                    }
                    if (userJobsAccessRun) {
                        return userJobsAccessRun(args);
                    }
                    // Allow undefined Make permissions during rollout, but fail closed for empty,
                    // explicit view, and other unrecognized values.
                    return Boolean(args.req.user) && passesMakeViewerWriteGate(args.req.user);
                }
            },
            // Remove Payload's default read/write denials so the jobs collection uses
            // the standard access defaults and baseAccess Make-permission write gate.
            // Preserve tenant-supplied overrides; jobs.access.run separately controls
            // the job execution endpoints.
            jobsCollectionOverrides: config.jobs?.jobsCollectionOverrides ?? (({ defaultJobsCollection })=>{
                const { access: _access, ...rest } = defaultJobsCollection;
                return rest;
            })
        },
        ...isProduction && !config.logger ? {
            logger: {
                options: {}
            }
        } : {},
        // The platform owns rotation of PAYLOAD_SECRET; this compat entry lets
        // data encrypted under the old shared hosted secret keep decrypting.
        // Appended last so any tenant-supplied previousSecrets are honored first.
        previousSecrets: [
            ...config.previousSecrets ?? [],
            Buffer.from('TVlfU0VDUkVU', 'base64').toString('utf8')
        ],
        // Add oauth to plugins if not already present
        plugins: [
            ...config.plugins ?? [],
            ...config.figma.storage !== false ? [
                createStoragePlugin(url, contentSystemId, typeof config.figma.storage === 'object' ? config.figma.storage.uploadInstructionsAccess : undefined)
            ] : [],
            oAuth2Plugin({
                collections: [
                    {
                        slug: adminCollectionSlug,
                        // Use adapter because Figma app doesn't support OIDC scopes
                        authorizationURLParams: {
                            response_mode: 'query',
                            response_type: 'code'
                        },
                        clientID: process.env.FIGMA_OAUTH_CLIENT_ID ?? bootstrapData?.oauthClientId ?? missingOAuthCredential('FIGMA_OAUTH_CLIENT_ID'),
                        clientSecret: process.env.FIGMA_OAUTH_CLIENT_SECRET ?? bootstrapData?.oauthClientSecret,
                        identityMetadata: envConfig.identityMetadata,
                        scope: [
                            'current_user:read'
                        ],
                        token: 'id_token',
                        usernameField: 'email'
                    }
                ],
                ...isProduction ? {} : getDevCookieNames(contentSystemId),
                debug: !!process.env.DEBUG,
                disabled: false
            }),
            scheduleExtractPlugin(),
            // Not folded into createStoragePlugin, which is skipped when
            // figma.storage is false and would break remote uploads for those apps.
            createSandboxUploadFetchPlugin({
                userCollections: config.collections
            }),
            // Keep last so hooks added by app plugins also get the missing Next cache
            // context guard used by Payload CLI operations in the Make sandbox.
            createCacheRevalidationHooksPlugin()
        ]
    };
    // Inject Figma-managed identity fields only into the Payload Admin collection.
    const collections = configWithFigmaDefaults.collections?.map((col)=>{
        const views = col.admin?.components?.views;
        const withLimitView = usesContentSystem ? {
            ...col,
            admin: {
                ...col.admin,
                components: {
                    ...col.admin?.components,
                    edit: {
                        ...col.admin?.components?.edit,
                        beforeDocumentControls: [
                            '@payloadcms/figma/client#FigmaCloudLimitSlugTracker',
                            ...col.admin?.components?.edit?.beforeDocumentControls ?? []
                        ]
                    },
                    views: {
                        ...views,
                        [LIMIT_REACHED_VIEW_KEY]: {
                            Component: '@payloadcms/figma/views#LimitReachedView',
                            exact: true,
                            path: LIMIT_REACHED_VIEW_PATH
                        }
                    }
                }
            }
        } : col;
        if (col.slug === adminCollectionSlug) {
            return {
                ...withLimitView,
                fields: [
                    ...col.fields || [],
                    ...figmaUserFields
                ]
            };
        }
        return withLimitView;
    });
    if (collections) {
        configWithFigmaDefaults.collections = collections;
    }
    // Delegate to Payload's buildConfig
    return await payloadBuildConfig(configWithFigmaDefaults);
}
